import { Effect, Path } from "effect";
import type { BanhMiPlugin } from "../type";
import { writer } from "../writers";
import { NodeFileSystem } from "@effect/platform-node";

/**
 * TS Plugin
 *
 * Generates BanhMi resources in a single TypeScript file.
 */
export const TSPlugin: BanhMiPlugin = Effect.fn(function* (props) {
  const domains = Object.entries(props.lock.domains);
  const views = Object.entries(props.lock.views);
  const generatedContent =
    "// This file is auto-generated by BanhMi. Do not edit this file directly.\n" +
    domains
      .map(
        (d) =>
          `/**
* Domain: ${d[0]}\n
* Length: ${d[1].map((b) => b.content).join("\n").length}\n
* Content:
${d[1].map((b) => `* ${b.content}`).join("\n")}
*/
export const ${d[0]} = ${JSON.stringify(
            d[1].map((b) => b.content).join("\n"),
            null,
            2,
          )} as const;\n\n`,
      )
      .join("") +
    views
      .map(
        (v) =>
          `/**
* View: ${v[0]}\n
* Length: ${v[1].map((b) => b.content).join("\n").length}\n
* Content:
${v[1].map((v) => `* ${v.content}`).join("\n")}
*/export const ${v[0]} = ${JSON.stringify(
            v[1].map((b) => b.content).join("\n"),
            null,
            2,
          )} as const;\n\n`,
      )
      .join("");
  yield* writer(props.props, `index.ts`, generatedContent).pipe(
    Effect.provide(NodeFileSystem.layer),
    Effect.provide(Path.layer),
    Effect.catchTag("PlatformError", (e) => Effect.logError(e)),
  );
});
